'use strict';
const $=s=>document.querySelector(s),audio=window.OktawkaEngine?.create($('#audio'))||$('#audio');
let tracks=[],current=-1,filter='All',view='discover',shuffle=false,liked=new Set(),toastTimer;
let prefs={quality:'original',eco:true};try{prefs={...prefs,...JSON.parse(localStorage.getItem('mono-prefs')||'{}')}}catch{}
function escapeHTML(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
function modal(html){$('#dialog').classList?.remove('artist-profile-dialog');$('#dialog-content').innerHTML=html;$('#dialog').showModal()}
$('#close').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog'))$('#dialog').close()};
function render(){const query=$('#search').value.toLowerCase();
const visible=tracks.map((t,i)=>({t,i})).filter(({t,i})=>(view!=='liked'||liked.has(i))&&(filter!=='Lossless'||t.lossless)&&`${t.title} ${t.artist}`.toLowerCase().includes(query));
$('#tracks').innerHTML=visible.length?visible.map(({t,i})=>`<button class="track" data-track="${i}"><span>${String(i+1).padStart(2,'0')}</span><div class="track-art">${i===current?'♫':'♪'}</div><div><b>${escapeHTML(t.title)}</b><small>${escapeHTML(t.artist)}</small></div><em>${escapeHTML(t.format)}</em></button>`).join(''):`<div class="empty">${query?'No matching tracks.':view==='liked'?'Your favorites will feel right at home here. Like a track while it plays.':'Your rotation starts with you.<br>Import audio files or connect a direct audio stream.'}</div>`;
$('#hero').hidden=view!=='discover';$('#section-title').textContent=view==='liked'?'Your collection, your way':filter==='All'?'Your collection, your way':filter==='Lossless'?'Every bit of your music':`${filter}, at your own pace`;$('.recent h2').textContent=view==='liked'?'Liked tracks':view==='library'?'Your music':'On your rotation';
}
function setView(v){view=v;$('#page-title').textContent=({discover:'Discover your next obsession.',search:'Find your next favorite.',library:'A home for your music.',liked:'Keep the good ones close.'})[v];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render();if(v==='search')$('#search').focus()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render()});
document.querySelectorAll('[data-mood]').forEach(b=>b.onclick=()=>{filter=b.dataset.mood;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x.dataset.filter===filter));setView('discover')});
$('#search').oninput=render;document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#dialog').open){e.preventDefault();$('#search').focus()}if(e.code==='Space'&&!['INPUT','BUTTON','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#dialog').open&&!$('#now-playing').open){e.preventDefault();toggle()}});
['add','local','hero-play','import-button'].forEach(id=>$('#'+id).onclick=()=>$('#files').click());
async function inspect(file){const q=window.MonoAudioQuality.parse(new Uint8Array(await file.slice(0,4096).arrayBuffer()));if(q)return {lossless:q.lossless,quality:q,sourceCodec:q.codec,format:`${q.codec} · ${q.bitDepth}-bit / ${q.sampleRate/1000} kHz`};return {lossless:false,sourceCodec:(file.name.split('.').pop()||'AUDIO').toUpperCase(),format:file.name.toLowerCase().endsWith('.flac')?'FLAC · unverified':(file.name.split('.').pop()||'AUDIO').toUpperCase()}}
$('#files').onchange=async e=>{for(const file of e.target.files){const meta=await inspect(file);tracks.push({title:file.name.replace(/\.[^.]+$/,''),artist:'Local file · on this device',url:URL.createObjectURL(file),...meta})}setView('library');toast('Music imported. Select a track to listen.');e.target.value=''};
async function play(i,fromCatalog=false){if(!fromCatalog){window.monoCancelCatalogPlayback?.();window.OktawkaFlow?.cancel()}if(i<0||i>=tracks.length)return;current=i;const t=tracks[i];audio.track=t;audio.src=t.url;window.OktawkaOnTrack?.(t);$('#seek').disabled=!!t.live;$('#now-title').textContent=t.title;$('#now-artist').textContent=t.artist;$('#now-artist').disabled=!t.artistId;$('#now-artist').onclick=()=>{if(t.artistId)window.monoOpenArtist?.(t.artistId,t.artist)};$('#mini-art').style.backgroundImage=t.artwork?'url("'+t.artwork+'")':'';$('#mini-art').style.backgroundSize='cover';$('#mini-art').innerHTML=t.artwork?'':'<span class="material-symbols-rounded" aria-hidden="true">music_note</span>';$('#quality').textContent=window.MonoAudioQuality.label(t);$('#quality').title=t.format+' · Source-file quality; device output may differ.';window.MonoAudioQuality.probe(t).then(q=>{if(q){t.quality=q;t.lossless=q.lossless;t.format=q.codec+' · '+q.bitDepth+'-bit / '+q.sampleRate/1000+' kHz'}if(current===i){$('#quality').textContent=window.MonoAudioQuality.label(t);$('#quality').title=t.format+' · Source-file quality; device output may differ.'}});$('#like').classList.toggle('liked',liked.has(i));$('#like').textContent=liked.has(i)?'♥':'♡';if('mediaSession'in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist});}render();try{await audio.play();if(current===i){$('#seek').disabled=!!t.live||audio.seekable===false;window.OktawkaOnPlaying?.(t)}}catch(e){toast(audio.lastError||e.message||'Playback unavailable. Check the audio format or stream access.')}}
$('#tracks').onclick=e=>{const t=e.target.closest('[data-track]');if(t)play(+t.dataset.track)};
function toggle(){window.monoCancelCatalogPlayback?.();if(current<0){if(tracks.length)play(0);else{$('#files').click()}return}if(audio.paused)audio.play().catch(()=>toast('Cannot play this source in this browser.'));else audio.pause()}
$('#play').onclick=toggle;audio.onplay=()=>{$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','Pause')};audio.onpause=()=>{$('#play').textContent='▶';$('#play').setAttribute('aria-label','Play')};
function next(dir=1){if(window.OktawkaFlow?.next(dir))return;if(!tracks.length)return;play(shuffle&&tracks.length>1?(current+1+Math.floor(Math.random()*(tracks.length-1)))%tracks.length:(current+dir+tracks.length)%tracks.length)}
$('#next').onclick=()=>next();$('#prev').onclick=()=>{if(!tracks[current]?.live&&audio.currentTime>3)audio.currentTime=0;else next(-1)};audio.onended=()=>{if(audio.loop)return;if(window.OktawkaFlow?.ended())return;if(current<tracks.length-1||shuffle)next()};audio.onerror=()=>toast('This source could not be played. Its codec, URL, or access may be unsupported.');
const time=s=>Number.isFinite(s)?`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`:'0:00';
audio.ontimeupdate=()=>{if(document.hidden)return;$('#elapsed').textContent=time(audio.currentTime);$('#seek').value=audio.duration?audio.currentTime/audio.duration*100:0};audio.onloadedmetadata=()=>{$('#duration').textContent=tracks[current]?.live?'LIVE':time(audio.duration)};$('#seek').oninput=e=>{if(audio.seekable!==false&&Number.isFinite(audio.duration))audio.currentTime=audio.duration*e.target.value/100};audio.volume=.8;$('#volume').oninput=e=>{audio.volume=+e.target.value;audio.muted=false};$('#mute').onclick=()=>{audio.muted=!audio.muted;$('#mute').textContent=audio.muted?'⊘':'◖))'};
$('#shuffle').onclick=()=>{shuffle=!shuffle;$('#shuffle').setAttribute('aria-pressed',shuffle)};$('#repeat').onclick=()=>{audio.loop=!audio.loop;$('#repeat').setAttribute('aria-pressed',audio.loop)};$('#like').onclick=()=>{if(current<0)return toast('Play a track to add it to your favorites.');if(liked.has(current))liked.delete(current);else liked.add(current);$('#like').classList.toggle('liked',liked.has(current));$('#like').textContent=liked.has(current)?'♥':'♡';render()};
function settings(){modal(`<div class="eyebrow">MAKE YOURSELF AT HOME</div><h2>Sound, your way.</h2><label for="preferred">Preferred source quality</label><select id="preferred"><option value="original">Original quality</option><option value="24">Prefer 24-bit FLAC</option><option value="16">Prefer 16-bit FLAC</option></select><p class="note">Saved for a future provider connection. Local files and direct streams play as supplied, without transcoding. Browser and audio hardware determine final output.</p><div class="row"><label for="eco">Low resource mode</label><input type="checkbox" id="eco"></div><p class="note">Native audio decoding, no visualizers, no background polling. UI progress updates stop when the app is hidden.</p><h3>Dolby Atmos</h3><p class="note">Not available in this player. Atmos needs an authorized encoded stream and a compatible licensed playback path. Stereo FLAC is not Atmos.</p><button class="primary" id="save">Save preferences</button>`);$('#preferred').value=prefs.quality;$('#eco').checked=prefs.eco;$('#save').onclick=()=>{prefs={quality:$('#preferred').value,eco:$('#eco').checked};try{localStorage.setItem('mono-prefs',JSON.stringify(prefs))}catch{}audio.preload=prefs.eco?'none':'metadata';$('#dialog').close();toast('Audio preferences saved')}}
['settings','audio-settings','profile','about'].forEach(id=>$('#'+id).onclick=settings);audio.preload=prefs.eco?'none':'metadata';
$('#connect').onclick=()=>{modal(`<div class="eyebrow">BRING YOUR OWN SOUND</div><h2>Connect a stream.</h2><p>Add a direct HTTPS audio URL you have access to. FLAC playback depends on browser support. API-based catalogs need a provider integration.</p><label for="stream-title">Track name</label><input id="stream-title" type="text" placeholder="My audio stream" maxlength="150"><label for="stream-url">Direct audio URL</label><input id="stream-url" type="url" placeholder="https://example.com/music.flac"><p class="note">Use a public or signed audio URL. Do not paste private API keys here.</p><button class="primary" id="add-stream">Add stream</button>`);$('#add-stream').onclick=()=>{let u;try{u=new URL($('#stream-url').value);if(u.protocol!=='https:')throw Error()}catch{return toast('Enter a valid HTTPS audio URL.')}tracks.push({title:$('#stream-title').value.trim()||'Connected stream',artist:u.hostname,url:u.href,lossless:false,format:'Stream · unverified'});$('#dialog').close();setView('library');toast('Stream added. Select it to start playback.')}};
$('#show-all').onclick=()=>{filter='All';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='All'));render();$('#cards').scrollIntoView({block:'center'})};
$('#queue').onclick=()=>{const plan=window.OktawkaFlow?.snapshot();if(plan?.items.length){modal(`<h2>Your album queue</h2><p class="note">Upcoming tracks are matched when their turn starts.</p>${plan.items.map((t,i)=>`<button class="track" data-planned="${i}"><span>${i===plan.position?'♫':i+1}</span><div><b>${escapeHTML(t.title)}</b><small>${escapeHTML(t.artist)}</small></div></button>`).join('')}`);$('#dialog-content').querySelectorAll('[data-planned]').forEach(b=>b.onclick=()=>window.OktawkaFlow.playAlbum(plan.items,Number(b.dataset.planned)));return}modal(`<h2>Up next</h2>${tracks.length?tracks.map((t,i)=>`<button class="track" data-q="${i}"><span>${i===current?'♫':i+1}</span><div><b>${escapeHTML(t.title)}</b><small>${escapeHTML(t.format)}</small></div></button>`).join(''):'<p>Your queue is empty. Add files or a stream to get started.</p>'}`);$('#dialog-content').querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{play(+b.dataset.q);$('#dialog').close()})};
if('mediaSession'in navigator){navigator.mediaSession.setActionHandler('play',()=>audio.play().catch(()=>{}));navigator.mediaSession.setActionHandler('pause',()=>audio.pause());navigator.mediaSession.setActionHandler('previoustrack',()=>next(-1));navigator.mediaSession.setActionHandler('nexttrack',()=>next())}
window.addEventListener('beforeunload',()=>tracks.forEach(t=>{if(t.url.startsWith('blob:'))URL.revokeObjectURL(t.url)}));render();
// Android wrapper only: keep a media foreground service alive while playing. Background pauses (track end, album gap) keep it, since Android 12+ forbids restarting it from the background.
if(window.location?.hostname==='app.oktawka.local'){const signal=s=>fetch('/native/playback?state='+s).catch(()=>{});audio.addEventListener('play',()=>signal('playing'));audio.addEventListener('pause',()=>{if(document.visibilityState==='visible')signal('stopped')})}
